package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
/** Explicit phone-to-glasses configuration; preview never starts automatically. */
final class PronunciationDialog {
 static void show(MainActivity owner){try{JSONObject state=ConversationWorkspace.snapshot(owner),dictionary=state.optJSONObject("pronunciation");if(!state.optBoolean("connected")||dictionary==null)throw new java.io.IOException("メガネと接続してから開き直してください");String original=dictionary.getString("text"),revision=dictionary.getString("revision");LinearLayout box=new LinearLayout(owner);box.setOrientation(1);TextView status=new TextView(owner);status.setText("メガネの辞書を編集します。1行に 単語=よみ、50件まで。保存・試聴はボタンを押した時だけ要求します。端末内の表示・元の回答は変えません。");box.addView(status);EditText text=new EditText(owner);text.setText(original);text.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(8000)});box.addView(text);EditText sample=new EditText(owner);sample.setHint("試聴する短い文章（160文字まで）");sample.setText("Rokidの電脳秘書ロキです。");sample.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(160)});box.addView(sample);Button save=new Button(owner),listen=new Button(owner),refresh=new Button(owner);save.setText("メガネに辞書を保存");listen.setText("保存済みの辞書で試聴");refresh.setText("反映結果を確認");box.addView(save);box.addView(listen);box.addView(refresh);String[] pending={""};
 save.setOnClickListener(v->{try{String raw=text.getText().toString();PronunciationPolicy.parse(raw);String id=java.util.UUID.randomUUID().toString();ConversationWorkspace.submit(owner,new JSONObject().put("requestId",id).put("action","pronunciation_save").put("baseRevision",revision).put("text",raw));pending[0]=id;save.setEnabled(false);listen.setEnabled(false);status.setText("保存を送信待ちへ追加しました。反映結果を確認してから、閉じて開き直してください。");}catch(Exception e){status.setText(e.getMessage());}});
 listen.setOnClickListener(v->{try{if(!text.getText().toString().equals(original))throw new java.io.IOException("編集した辞書を保存し、反映を確認してから開き直してください");String id=java.util.UUID.randomUUID().toString();ConversationWorkspace.submit(owner,new JSONObject().put("requestId",id).put("action","pronunciation_preview").put("baseRevision",revision).put("sample",sample.getText().toString()));pending[0]=id;status.setText("試聴を送信待ちへ追加しました。反映結果と実際の音声を確認してください。");}catch(Exception e){status.setText(e.getMessage());}});
 refresh.setOnClickListener(v->{JSONObject latest=ConversationWorkspace.snapshot(owner);status.setText(!latest.optBoolean("connected")?"メガネの接続状態を確認できません":pending[0].isEmpty()?"保存・試聴はまだ要求していません":pending[0].equals(latest.optString("commandId"))?latest.optString("commandPhase")+"："+latest.optString("commandStatus"):"メガネからの結果待ちです。自動再送はしません。");});ScrollView scroll=new ScrollView(owner);scroll.addView(box);new AlertDialog.Builder(owner).setTitle("メガネの読み上げ辞書・試聴").setView(scroll).setPositiveButton("閉じる",null).show();}catch(Exception e){new AlertDialog.Builder(owner).setMessage(e.getMessage()).setPositiveButton("閉じる",null).show();}}
 private PronunciationDialog(){}
}
